def normalize_existing_leads(apps, schema_editor):
    Lead = apps.get_model('crm', 'Lead')
    Sequence = apps.get_model('crm', 'LeadSequence')
    counters = {}
    for value in Lead.objects.exclude(lead_no__isnull=True).values_list('lead_no', flat=True):
        try:
            _, year, number = value.split('-')
            counters[int(year)] = max(counters.get(int(year), 0), int(number))
        except (AttributeError, TypeError, ValueError):
            pass
    for lead in Lead.objects.all().order_by('id'):
        if lead.status == 'Follow Up':
            lead.status = 'Follow-up'
        elif lead.status == 'Converted':
            lead.status = 'Won'
        if not lead.lead_no:
            year = lead.created_on.year if lead.created_on else 2026
            counters[year] = counters.get(year, 0) + 1
            lead.lead_no = f"LD-{year}-{counters[year]:06d}"
        lead.save(update_fields=['lead_no', 'status'])
    for year, number in counters.items():
        Sequence.objects.update_or_create(year=year, defaults={'last_number': number})


